def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]
    opp_coops = sum(1 for h in history if h[1] == 'C')
    opp_rate = opp_coops / n

    # Check for exploit mode: we probed, opponent didn't retaliate,
    # and opponent hasn't defected since that confirmation.
    exploit = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i+1][0] == 'C' and history[i+1][1] == 'C':
                defected_after = False
                for j in range(i + 2, n):
                    if history[j][1] == 'D':
                        defected_after = True
                        break
                if not defected_after:
                    exploit = True
                    break

    if exploit:
        if last_opp == 'D':
            return 'C'
        else:
            return 'D'

    if opp_rate < 0.4:
        return 'D'

    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        if opp_rate > 0.6:
            return 'C'
        else:
            return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        my_defects = sum(1 for h in history if h[0] == 'D')
        if my_defects == 0 and n >= 9 and opp_rate > 0.8:
            return 'D'
        return 'C'

    return 'C'
